  /// A JSON value representation.
  public enum JsonElement: Codable, Sendable, Equatable {
    case string(String)
    case number(Double)
    case bool(Bool)
    case object([String: JsonElement], [String])
    case array([JsonElement])
    case null

    private struct DynamicCodingKey: CodingKey {
      var stringValue: String
      var intValue: Int?
      init?(stringValue: String) { self.stringValue = stringValue }
      init?(intValue: Int) {
        self.intValue = intValue
        self.stringValue = "\(intValue)"
      }
    }

    public init(from decoder: Decoder) throws {
      if let container = try? decoder.container(keyedBy: DynamicCodingKey.self) {
        var dict = [String: JsonElement]()
        var orderedKeys = [String]()
        for key in container.allKeys {
          let k = key.stringValue
          dict[k] = try container.decode(JsonElement.self, forKey: key)
          orderedKeys.append(k)
        }
        if let keysVal = dict["__keys__"], case .array(let keysArr) = keysVal {
          orderedKeys = keysArr.compactMap {
            if case .string(let s) = $0 { return s }
            return nil
          }
          dict.removeValue(forKey: "__keys__")
        }
        self = .object(dict, orderedKeys)
        return
      }
      let container = try decoder.singleValueContainer()
      if container.decodeNil() {
        self = .null
      } else if let bool = try? container.decode(Bool.self) {
        self = .bool(bool)
      } else if let num = try? container.decode(Double.self) {
        self = .number(num)
      } else if let str = try? container.decode(String.self) {
        self = .string(str)
      } else if let arr = try? container.decode([JsonElement].self) {
        self = .array(arr)
      } else {
        throw DecodingError.dataCorruptedError(
          in: container,
          debugDescription: "Unsupported JSON value",
        )
      }
    }

    public func encode(to encoder: Encoder) throws {
      switch self {
      case .string(let str):
        var container = encoder.singleValueContainer()
        try container.encode(str)
      case .number(let num):
        var container = encoder.singleValueContainer()
        try container.encode(num)
      case .bool(let bool):
        var container = encoder.singleValueContainer()
        try container.encode(bool)
      case .object(let dict, let orderedKeys):
        var container = encoder.container(keyedBy: DynamicCodingKey.self)
        for key in orderedKeys {
          if let val = dict[key], let k = DynamicCodingKey(stringValue: key) {
            try container.encode(val, forKey: k)
          }
        }
      case .array(let arr):
        var container = encoder.unkeyedContainer()
        for element in arr {
          try container.encode(element)
