        var container = encoder.singleValueContainer()
        try container.encode(double)
      } else if let string = value as? String {
        var container = encoder.singleValueContainer()
        try container.encode(string)
      } else if let array = value as? [Any?] {
        var container = encoder.unkeyedContainer()
        for element in array {
          try container.encode(AnyEncodableValue(element))
        }
      } else if let array = value as? [Any] {
        var container = encoder.unkeyedContainer()
        for element in array {
          try container.encode(AnyEncodableValue(element))
        }
      } else if let dict = value as? [String: Any?] {
        let keys = (dict["__keys__"] as? [String]) ?? Array(dict.keys.filter { $0 != "__keys__" })
        var container = encoder.container(keyedBy: StringCodingKey.self)
        for key in keys where key != "__keys__" {
          try container.encode(AnyEncodableValue(dict[key] as Any?), forKey: StringCodingKey(key))
        }
      } else if let dict = value as? [String: Any] {
        let keys = (dict["__keys__"] as? [String]) ?? Array(dict.keys.filter { $0 != "__keys__" })
        var container = encoder.container(keyedBy: StringCodingKey.self)
        for key in keys where key != "__keys__" {
          try container.encode(AnyEncodableValue(dict[key]), forKey: StringCodingKey(key))
        }
      } else if let encodable = value as? any Encodable {
        try AnyEncodable(encodable).encode(to: encoder)
      } else {
        var container = encoder.singleValueContainer()
        try container.encode(String(describing: value))
      }
    }
  }

  fileprivate struct StringCodingKey: CodingKey {
    let stringValue: String
    let intValue: Int? = nil
    init(_ string: String) { self.stringValue = string }
    init?(stringValue: String) { self.stringValue = stringValue }
    init?(intValue: Int) { return nil }
  }

  fileprivate static func unwrapOptional(_ any: Any?) -> Any? {
    guard let any = any else { return nil }
    let mirror = Mirror(reflecting: any)
    if mirror.displayStyle == .optional {
      if let child = mirror.children.first {
        return unwrapOptional(child.value)
      }
      return nil
    }
    return any
  }

  fileprivate static func jsonElementToObject(_ elem: JsonElement?) -> Any? {
    guard let elem = elem else { return nil }
    switch elem {
    case .string(let s): return s
    case .number(let n):
      if n.rounded() == n && n >= Double(Int.min) && n <= Double(Int.max) {
        return Int(n)
      }
      return n
    case .bool(let b): return b
    case .object(let dict, let orderedKeys):
      var res = [String: Any?]()
      for (k, v) in dict {
        res[k] = jsonElementToObject(v)
      }
      res["__keys__"] = orderedKeys
      return res
    case .array(let arr):
      return arr.map { jsonElementToObject($0) }
    case .null: return nil
    }
  }

  fileprivate static func inputToObject(_ input: Any?) -> Any? {
    guard let unwrapped = unwrapOptional(input) else { return nil }
    if let str = unwrapped as? String { return str }
    if let bool = unwrapped as? Bool { return bool }
    if let int = unwrapped as? Int { return int }
    if let int64 = unwrapped as? Int64 { return int64 }
    if let double = unwrapped as? Double { return double }
    if let dict = unwrapped as? [String: Any?] {
      var res = [String: Any?]()
      let orderedKeys =
        (dict["__keys__"] as? [String]) ?? Array(dict.keys.filter { $0 != "__keys__" })
      for (k, v) in dict where k != "__keys__" {
        res[k] = inputToObject(v)
      }
      res["__keys__"] = orderedKeys
      return res
    }
    if let dict = unwrapped as? [String: Any] {
      var res = [String: Any?]()
      let orderedKeys =
        (dict["__keys__"] as? [String]) ?? Array(dict.keys.filter { $0 != "__keys__" })
      for (k, v) in dict where k != "__keys__" {
        res[k] = inputToObject(v)
      }
      res["__keys__"] = orderedKeys
      return res
    }
    if let arr = unwrapped as? [Any] {
      return arr.compactMap { inputToObject($0) }
    }
    let mirror = Mirror(reflecting: unwrapped)
    if mirror.displayStyle == .struct || mirror.displayStyle == .class || !mirror.children.isEmpty {
      var res = [String: Any?]()
      var orderedKeys = [String]()
      for child in mirror.children {
        if let label = child.label {
          res[label] = inputToObject(child.value)
          orderedKeys.append(label)
        }
      }
      if !orderedKeys.isEmpty {
        res["__keys__"] = orderedKeys
        return res
      }
    }
    if let encodable = unwrapped as? any Encodable {
      let encoder = JSONEncoder()
      if let data = try? encoder.encode(AnyEncodable(encodable)),
        let jsonElem = try? JSONDecoder().decode(JsonElement.self, from: data)
      {
        return jsonElementToObject(jsonElem)
      }
    }
    return unwrapped
  }

  fileprivate static func evaluate(_ expression: Spec.Expression, _ val: Any?) -> Any? {
    let unwrappedVal = unwrapOptional(val)
    switch expression {
    case .kindInput:
      return unwrappedVal
    case .kindProperty(let prop):
      let leftVal = evaluate(prop.left, unwrappedVal)
      if let dict = leftVal as? [String: Any?] {
        return unwrapOptional(dict[prop.property] as Any?)
      }
      if let dict = leftVal as? [String: Any] {
        return unwrapOptional(dict[prop.property])
      }
      return nil
    }
  }

  fileprivate static func indent(_ text: String, _ spaces: String) -> String {
    if spaces.isEmpty { return text }
    return text.replacingOccurrences(of: "\n", with: "\n" + spaces)
  }

  fileprivate static func formatTable(_ v: Any?, _ fmt: Spec.InsertFormat) -> String {
    guard let unwrappedV = unwrapOptional(v) else { return "" }
    guard let list = unwrappedV as? [Any], !list.isEmpty else { return "" }
    let separator = fmt == .csv ? "," : "\t"
    guard let firstRaw = unwrapOptional(list.first) as? [String: Any?] else { return "" }
    let headers: [String]
    if let ordered = firstRaw["__keys__"] as? [String] {
      headers = ordered.filter { $0 != "__keys__" }
    } else {
      headers = Array(firstRaw.keys.filter { $0 != "__keys__" }).sorted()
    }
    var lines = [headers.joined(separator: separator)]
    for item in list {
      guard let row = unwrapOptional(item) as? [String: Any?] else { continue }
      var cells = [String]()
      for key in headers {
        let cellVal = unwrapOptional(row[key] as Any?)
        let str = cellVal != nil ? "\(cellVal!)" : ""
        if fmt == .csv {
          if str.contains("\"") || str.contains(",") || str.contains("\n") || str.contains("\r") {
            let escaped = str.replacingOccurrences(of: "\"", with: "\"\"")
            cells.append("\"\(escaped)\"")
          } else {
            cells.append(str)
          }
        } else {
          let escaped =
            str
            .replacingOccurrences(of: "\\", with: "\\\\")
            .replacingOccurrences(of: "\t", with: "\\t")
            .replacingOccurrences(of: "\n", with: "\\n")
            .replacingOccurrences(of: "\r", with: "\\r")
          cells.append(escaped)
        }
      }
      lines.append(cells.joined(separator: separator))
    }
    return lines.joined(separator: "\n")
  }

  fileprivate static func formatValue(_ v: Any?, _ fmt: Spec.InsertFormat?) -> String {
    guard let unwrapped = unwrapOptional(v) else { return "" }
    guard let fmt = fmt else {
      return "\(unwrapped)"
    }
    switch fmt {
    case .text:
      return "\(unwrapped)"
    case .json:
      let cleanV = cleanForSerialization(unwrapped)
      if let data = try? JSONSerialization.data(
        withJSONObject: cleanV, options: [.prettyPrinted, .sortedKeys]),
        let str = String(data: data, encoding: .utf8)
      {
        return str
      }
      return "\(unwrapped)"
    case .yaml:
      let cleanV = cleanForSerialization(unwrapped)
      if let yaml = try? Yams.dump(object: cleanV) {
        return yaml.trimmingCharacters(in: CharacterSet.newlines)
      }
      return "\(unwrapped)"
    case .toon:
      let encoder = TOONEncoder()
      if let data = try? encoder.encode(AnyEncodableValue(unwrapped)),
        let str = String(data: data, encoding: .utf8)
      {
        return str
      }
      return "\(unwrapped)"
    case .csv, .tsv:
      return formatTable(unwrapped, fmt)
    }
  }

  fileprivate static func cleanForSerialization(_ v: Any?) -> Any {
    guard let val = unwrapOptional(v) else { return NSNull() }
    if let dict = val as? [String: Any?] {
      var res = [String: Any]()
      for (k, subVal) in dict where k != "__keys__" {
        res[k] = cleanForSerialization(subVal)
      }
      return res
    }
    if let dict = val as? [String: Any] {
      var res = [String: Any]()
      for (k, subVal) in dict where k != "__keys__" {
        res[k] = cleanForSerialization(subVal)
      }
      return res
    }
    if let arr = val as? [Any] {
      return arr.map { cleanForSerialization($0) }
    }
    return val
  }

  fileprivate static func renderBody(
    _ body: [Spec.BodyPiece]?,
    _ inp: Any?,
    _ snippets: [String: Spec.Snippet],
  ) -> String {
    guard let body = body, !body.isEmpty else { return "" }
    var result = ""
    for piece in body {
      switch piece {
      case .kindText(let p):
        result += p.text
      case .kindInsertVal(let p):
        let val = evaluate(p.val, inp)
        let formatted = formatValue(val, p.format)
        result += indent(formatted, p.indent)
      case .kindInsertSnippet(let p):
        guard let snippet = snippets[p.snippet] else {
          fatalError("Snippet not found: \(p.snippet)")
        }
        let rendered = renderSnippet(snippet, inp, snippets)
        result += indent(rendered, p.indent)
      }
    }
    return result
  }

  fileprivate static func renderSnippet(
    _ snippet: Spec.Snippet,
    _ inp: Any?,
    _ snippets: [String: Spec.Snippet],
  ) -> String {
    switch snippet {
    case .kindSnippet(let s):
      return renderBody(s.body, inp, snippets)
    case .kindSnippetIf(let s):
      let evalResult = evaluate(s.expression, inp)
      var condition = false
      switch s.is {
      case .notEmpty:
        if let col = evalResult as? [Any] {
          condition = !col.isEmpty
        } else if let dict = evalResult as? [String: Any] {
          condition = !dict.isEmpty
        } else if let str = evalResult as? String {
          condition = !str.isEmpty
        } else {
          condition = evalResult != nil
        }
      case .notNull:
        condition = evalResult != nil
      case .true:
        if let b = evalResult as? Bool {
          condition = b
        } else if let str = evalResult as? String {
          condition = !str.isEmpty
        } else if let num = evalResult as? Int {
          condition = num != 0
        } else if let num = evalResult as? Double {
          condition = num != 0
        } else {
          condition = evalResult != nil
        }
      }
      return renderBody(condition ? s.then : s.else, inp, snippets)
    case .kindSnippetSwitch(let s):
      let switchVal = evaluate(s.expression, inp)
      let switchKey: String
      if let b = switchVal as? Bool {
        switchKey = b ? "true" : "false"
      } else if let val = switchVal {
        switchKey = "\(val)"
      } else {
        switchKey = ""
      }
      guard let branch = s.branches[switchKey] else {
        fatalError("Branch not found: \(switchKey)")
      }
      return renderBody(branch, inp, snippets)
    }
  }

  fileprivate static func renderExamples(
    _ examples: [Spec.FewShotExample]?,
    _ userBody: [Spec.BodyPiece]?,
    _ tmpl: Spec.Template,
  ) -> [FewShotExample] {
    guard let examples = examples, !examples.isEmpty else { return [] }
    var result = [FewShotExample]()
    for ex in examples {
      let exInputObj = jsonElementToObject(ex.input)
      let exOutputObj = jsonElementToObject(ex.output)
      let userMessage = renderBody(userBody, exInputObj, tmpl.snippets)

      var intermediateSteps = [IntermediateStepExample]()
      for step in ex.intermediateSteps {
        var toolCalls = [ToolCallExample]()
        for tc in step.toolCalls {
          let stringifiedInput = formatValue(jsonElementToObject(tc.input), .json)
          let stringifiedOutput = formatValue(jsonElementToObject(tc.output), .json)
          toolCalls.append(
            ToolCallExample(
              callId: tc.callId,
              toolName: tc.toolName,
              stringifiedInput: stringifiedInput,
              stringifiedOutput: stringifiedOutput,
            )
          )
        }
        intermediateSteps.append(IntermediateStepExample(toolCalls: toolCalls))
      }

      let outputFormat: Spec.InsertFormat = tmpl.outputFormat == .json ? .json : .text
      let response = formatValue(exOutputObj, outputFormat)

      result.append(
        FewShotExample(
          userMessage: userMessage,
          intermediateSteps: intermediateSteps,
          response: response,
        )
      )
    }
    return result
  }

  fileprivate static func doRender<Output, ToolExecutor>(
    _ spec: Spec.Templates,
    _ templateId: String,
    _ input: Any,
    _ outputType: Output.Type? = nil,
  ) -> Prompt<Output, ToolExecutor> {
    guard let template = spec.templates[templateId] else {
      fatalError("Template not found: \(templateId)")
    }

    let inputObj = inputToObject(input)
    let snippets = template.snippets
    let contents = template.contents

    var metaElement: JsonElement? = nil
    var systemMessage: String = ""
    var userMessage: String = ""
    var examples: [FewShotExample] = []

    switch contents {
    case .kindNoVariants(let noVariants):
      let content = noVariants.content
      metaElement = content.meta
      systemMessage = renderBody(content.system, inputObj, snippets)
      let userBody = content.user ?? []
      userMessage = renderBody(userBody, inputObj, snippets)
      examples = renderExamples(content.examples, userBody, template)
    case .kindVariants(let variants):
      guard let inputDict = inputObj as? [String: Any],
        let variant = inputDict["variant"] as? String
      else {
        fatalError("Input for template with variants must contain 'variant'")
      }
      guard let variantContent = variants.variants[variant] else {
        fatalError("Unknown variant: \(variant)")
      }
      let defaultContent = variants.defaultContent

      metaElement = variantContent.meta ?? defaultContent.meta
      let systemBody = variantContent.system ?? defaultContent.system ?? []
      let userBody = variantContent.user ?? defaultContent.user ?? []
      systemMessage = renderBody(systemBody, inputObj, snippets)
      userMessage = renderBody(userBody, inputObj, snippets)
      let rawExamples = variantContent.examples ?? defaultContent.examples
      examples = renderExamples(rawExamples, userBody, template)
    }

    let meta: Meta
    if let metaElement = metaElement, let metaObj = jsonElementToObject(metaElement) {
      meta = parseMeta(metaObj)
    } else {
      meta = parseMeta(nil)
    }

    var tools = [String: Tool]()
    for templateTool in template.tools {
      if let specTool = spec.tools[templateTool.id] {
        tools[templateTool.name] = Tool(
          name: templateTool.name,
          description: specTool.description,
          inputJsonSchema: specTool.inputJsonSchema,
        )
      }
    }

    let outputFormat: OutputFormat
    let fromJson: @Sendable (Data) throws -> Output
    if template.outputFormat == .json {
      let schemaJson: String
      if let obj = jsonElementToObject(template.outputJsonSchema),
        let data = try? JSONSerialization.data(
          withJSONObject: obj, options: [.prettyPrinted, .sortedKeys]),
        let str = String(data: data, encoding: .utf8)
      {
        schemaJson = str
      } else {
        schemaJson = "{}"
      }
      fromJson = { data in
        if let decodableType = (outputType ?? Output.self) as? any Decodable.Type {
          return try Foundation.JSONDecoder().decode(decodableType, from: data) as! Output
        }
        fatalError("Expected Decodable output type for JSON template: \(templateId)")
      }
      outputFormat = .json(
        JsonOutputFormat(
          stringifiedJsonSchema: schemaJson,
          jsonSchema: template.outputJsonSchema,
        )
      )
    } else {
      fromJson = { data in
        if let str = (String(data: data, encoding: .utf8) ?? String(decoding: data, as: UTF8.self))
          as? Output
        {
          return str
        }
        fatalError("Expected String output type for text template: \(templateId)")
      }
      outputFormat = .text
    }

    let resolvedTemplateId = TemplateId.allCases.first(where: { $0.description == templateId })!

    return Prompt<Output, ToolExecutor>(
      meta: meta,
      systemMessage: systemMessage,
      userMessage: userMessage,
      examples: examples,
      tools: tools,
      outputFormat: outputFormat,
      templateId: resolvedTemplateId,
      fromJson: fromJson,
    )
  }

  fileprivate static func doParseResponse<Output>(
    _ response: String,
    outputFormat: OutputFormat,
    templateId: TemplateId,
    fromJson: @Sendable (Data) throws -> Output,
  ) throws -> Output {
    switch outputFormat {
    case .json:
      var cleaned = response.trimmingCharacters(in: .whitespacesAndNewlines)
      if cleaned.hasPrefix("```") {
        if cleaned.hasPrefix("```json") {
          cleaned = String(cleaned.dropFirst("```json".count))
        } else {
          cleaned = String(cleaned.dropFirst("```".count))
        }
        if cleaned.hasSuffix("```") {
          cleaned = String(cleaned.dropLast("```".count))
        }
        cleaned = cleaned.trimmingCharacters(in: .whitespacesAndNewlines)
      }
      let data = Data(cleaned.utf8)
      do {
        return try fromJson(data)
      } catch {
        throw DecodingError.dataCorrupted(
          DecodingError.Context(
            codingPath: [],
            debugDescription: "Template '\(templateId)': \(error)",
          ),
        )
      }
    case .text:
      if let res = response as? Output {
        return res
      }
      let data = Data(response.utf8)
      return try fromJson(data)
    }
  }

  fileprivate static func doExecuteTools<ToolExecutor: Sendable>(
    _ toolCalls: some Sequence<ToolCall>,
    templateId: TemplateId,
    toolExecutor: ToolExecutor,
  ) async throws -> [ToolCallResponse] {
    let namespace = templateId.description.split(separator: ":").first.map(String.init) ?? ""
    return try await withThrowingTaskGroup(of: (Int, ToolCallResponse).self) {
      group in
      for (index, call) in toolCalls.enumerated() {
        group.addTask {
          let result = try await executeToolCall(
            toolCall: call,
            namespace: namespace,
            executor: toolExecutor,
          )
          return (index, result)
        }
      }
      var results = [(Int, ToolCallResponse)]()
      for try await item in group {
        results.append(item)
      }
      return results.sorted(by: { $0.0 < $1.0 }).map { $0.1 }
    }
  }

  /// Use this with external frameworks that support template override injection
  /// for experimentation or A/B testing.
  ///
  /// When using overrides, inject the resulting `Prompts` instance as a dependency
  /// rather than relying on `prompts`.
  public enum TemplateOverrider {
    /// Returns the current template data as JSON-encoded data.
    public static func templatesData() throws -> Data {
      let encoder = JSONEncoder()
      return try encoder.encode(_templatesData)
    }

    /// Applies overrides from JSON data and returns a new `Prompts` instance.
    public static func applyOverrides(_ overridesData: Data) throws -> Prompts {
      let decoder = JSONDecoder()
      guard let json = try JSONSerialization.jsonObject(with: overridesData) as? [String: Any],
        let sig = json["signature"] as? String
      else {
        throw NSError(
          domain: "TemplateOverrider", code: 1,
          userInfo: [NSLocalizedDescriptionKey: "Invalid overrides format"],
        )
      }
      if sig != _templatesData.signature {
        throw NSError(
          domain: "TemplateOverrider", code: 2,
          userInfo: [NSLocalizedDescriptionKey: "Signature mismatch"],
        )
      }
      var mergedTemplates = _templatesData.templates
      if let templatesObj = json["templates"] as? [String: Any] {
        let templatesDataRaw = try JSONSerialization.data(withJSONObject: templatesObj)
        let overrideTemplates = try decoder.decode(
          [String: Spec.Template].self,
          from: templatesDataRaw,
        )
        for (k, v) in overrideTemplates {
          mergedTemplates[k] = v
        }
      }
      var mergedTools = _templatesData.tools
      if let toolsObj = json["tools"] as? [String: Any] {
        let toolsDataRaw = try JSONSerialization.data(withJSONObject: toolsObj)
        let overrideTools = try decoder.decode([String: Spec.Tool].self, from: toolsDataRaw)
        for (k, v) in overrideTools {
          mergedTools[k] = v
        }
      }
      let mergedData = Spec.Templates(
        edition: _templatesData.edition,
        signature: _templatesData.signature,
        templates: mergedTemplates,
        tools: mergedTools,
        singleNamespace: _templatesData.singleNamespace,
        sourceFiles: _templatesData.sourceFiles,
      )
      return Prompts(mergedData)
    }
  }

